<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Listener;

use Civi\Lughauth\Features\Document\Rendering\Application\Service\DocumentAssetDumpService;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetDeleteEvent;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetEvent;

/**
 * Keeps the local .assets/snippets/ directory in sync with the database.
 *
 * Registered for SnippetAssetEvent so it handles all sub-events (Create, Update,
 * Enable, Disable, Delete) via a single listener entry.
 *
 * - Delete  → remove the file from disk (blob already gone from storage).
 * - Others  → write to disk when enabled; remove when disabled.
 */
class SnippetAssetDiskSyncListener
{
    public function __construct(
        private readonly DocumentAssetDumpService $assetDumpService,
    ) {
    }

    public function __invoke(SnippetAssetEvent $event): void
    {
        if ($event instanceof SnippetAssetDeleteEvent) {
            $this->assetDumpService->removeSnippetAsset($event->payload);
        } else {
            $this->assetDumpService->dumpSnippetAsset($event->payload);
        }
    }
}
